/**
 * The Java a build tool wrote.
 *
 * Every walker in Kiwi skips `target`, `build` and `out`, and it has to: they
 * hold thousands of class files, jars and packaging leftovers that would drown
 * a file search. But annotation processors put real, navigable Java in there
 * too — MapStruct's `*MapperImpl`, Immutables' `Immutable*`, Dagger's
 * components, anything generated by `javac -s`. Those classes are compiled
 * against, appear in stack traces and are stepped through in a debugger, and
 * until now Kiwi could not find one by name or open one by clicking it. The
 * status bar even counted them, always as zero, because the walk that fed the
 * count could not reach them.
 *
 * So the skip becomes narrower rather than absent: a build directory is still
 * skipped, except along the paths where a build tool is known to put sources.
 * Nothing else in `target` is opened, and the index does not grow by a class
 * file.
 */

const path = require("node:path");

/** Directories that hold build output rather than sources. */
const BUILD_DIRECTORIES = new Set(["target", "build", "out", "bin"]);

/**
 * The paths under a build directory that hold generated Java.
 *
 * Written as segment lists rather than as one regular expression because the
 * walk asks a different question — "may I enter this directory" — and has to
 * answer it for a prefix of a path, before the rest of it exists.
 */
const GENERATED_PATHS = [
  // Maven: the default output of `javac -s`, plus what build-helper adds.
  ["target", "generated-sources"],
  ["target", "generated-test-sources"],
  // Gradle: annotation processing, and the older kapt/apt layout.
  ["build", "generated", "sources"],
  ["build", "generated", "source"],
  ["build", "generated-src"],
];

/** Splits a path into lower-case segments, whichever separator it used. */
function segmentsOf(candidate) {
  return String(candidate || "").replace(/\\/g, "/").toLowerCase().split("/").filter(Boolean);
}

/**
 * Whether a walk may descend into a directory.
 *
 * Answers for a directory that has not been walked into yet, so it must accept
 * every prefix of a generated path: `target` alone is not generated sources,
 * but refusing it would make `target/generated-sources` unreachable.
 */
function isGeneratedBranch(relativePath) {
  const segments = segmentsOf(relativePath);
  if (!segments.length) return false;
  return GENERATED_PATHS.some((generated) => {
    const shared = Math.min(segments.length, generated.length);
    for (let index = 0; index < shared; index += 1) {
      if (segments[index] !== generated[index]) return false;
    }
    return true;
  });
}

/**
 * Whether a directory should be skipped, given where it sits.
 *
 * `relativePath` is measured from the project root, because the same name
 * means different things in different places: `src/main/java/.../build` is a
 * package called build, and skipping it would hide a source tree.
 */
function isSkippedBuildDirectory(name, relativePath) {
  if (!BUILD_DIRECTORIES.has(String(name || "").toLowerCase())) return false;
  if (isGeneratedBranch(relativePath)) return false;
  // `de.beispiel.build` is a package, not build output, and skipping it lost
  // a whole source tree. Nothing a build tool writes sits under a source root,
  // so an earlier `src` segment settles it. A Gradle subproject's own `build`
  // has no such segment and stays skipped.
  const segments = segmentsOf(relativePath);
  return !segments.slice(0, -1).includes("src");
}

/**
 * Whether a walk may collect a file it has reached.
 *
 * Descending and collecting are two different questions, and answering only
 * the first was wrong: to reach `target/generated-sources` the walk has to
 * enter `target`, and it then saw everything else sitting directly in there.
 * A file is collected when nothing on its way was build output — or when it is
 * itself one of the generated sources that made the descent worthwhile.
 */
function isCollectableFile(relativePath) {
  const segments = segmentsOf(relativePath);
  const directories = segments.slice(0, -1);
  const sourceRoot = directories.indexOf("src");
  const buildIndex = directories.findIndex((segment, index) =>
    BUILD_DIRECTORIES.has(segment) && (sourceRoot < 0 || index < sourceRoot));
  if (buildIndex < 0) return true;
  return isGeneratedSource(relativePath);
}

/** Whether a file is generated Java that is worth indexing. */
function isGeneratedSource(relativePath) {
  const segments = segmentsOf(relativePath);
  if (!segments.at(-1)?.endsWith(".java")) return false;
  return GENERATED_PATHS.some((generated) =>
    generated.every((segment, index) => segments[index] === segment));
}

/** The path of `absolute` relative to `root`, in the form the rules expect. */
function relativeTo(root, absolute) {
  const relative = path.relative(path.resolve(root), path.resolve(absolute));
  return relative.startsWith("..") ? "" : relative;
}

module.exports = {
  BUILD_DIRECTORIES,
  isCollectableFile,
  GENERATED_PATHS,
  isGeneratedBranch,
  isGeneratedSource,
  isSkippedBuildDirectory,
  relativeTo,
};
